:root {
  color-scheme: light;
  --ink: #111815;
  --ink-soft: #2d3831;
  --muted: #66736c;
  --subtle: #8d9991;
  --bg: #f2f4ee;
  --panel: #ffffff;
  --panel-strong: #f7f8f3;
  --panel-tint: #eef6f1;
  --line: #d7ded6;
  --line-strong: #aebdb4;
  --teal: #0d6f61;
  --teal-dark: #084f46;
  --teal-soft: #e2f3ec;
  --amber: #b86e17;
  --amber-soft: #fff0d8;
  --blue: #315f93;
  --blue-soft: #e7eff8;
  --green: #247747;
  --green-soft: #e4f2e8;
  --red: #b33b30;
  --red-soft: #fde8e5;
  --soft-teal: var(--teal-soft);
  --soft-amber: var(--amber-soft);
  --soft-blue: var(--blue-soft);
  --soft-green: var(--green-soft);
  --soft-red: var(--red-soft);
  --shadow: 0 18px 45px rgba(28, 42, 38, 0.11);
  --shadow-soft: 0 12px 30px rgba(28, 42, 38, 0.08);
  --radius: 8px;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-family: var(--sans);
  color: var(--ink);
  background: var(--bg);
}

* {
  box-sizing: border-box;
  letter-spacing: 0;
}

main,
section,
article,
div,
header,
nav,
aside {
  min-width: 0;
}

html {
  min-width: 320px;
  background: var(--bg);
}

body {
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  color: var(--ink);
  background:
    linear-gradient(180deg, rgba(13, 111, 97, 0.1), transparent 270px),
    linear-gradient(135deg, transparent 0 70%, rgba(184, 110, 23, 0.08) 70% 100%),
    repeating-linear-gradient(90deg, rgba(17, 24, 21, 0.025) 0 1px, transparent 1px 92px),
    var(--bg);
}

body.quiet-focus-mode {
  background:
    radial-gradient(circle at 18% 0%, rgba(226, 243, 236, 0.95), transparent 360px),
    linear-gradient(180deg, rgba(13, 111, 97, 0.06), transparent 300px),
    repeating-linear-gradient(90deg, rgba(17, 24, 21, 0.015) 0 1px, transparent 1px 120px),
    #f6f8f3;
}

body.serenity-mode {
  background:
    radial-gradient(circle at 12% 0%, rgba(226, 243, 236, 0.9), transparent 380px),
    radial-gradient(circle at 88% 8%, rgba(231, 239, 248, 0.72), transparent 360px),
    linear-gradient(180deg, rgba(13, 111, 97, 0.045), transparent 320px),
    repeating-linear-gradient(90deg, rgba(17, 24, 21, 0.012) 0 1px, transparent 1px 140px),
    #f7faf4;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  border: 0;
  cursor: pointer;
}

button:disabled,
select:disabled,
input:disabled,
textarea:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}

.app-toast {
  position: fixed;
  left: 50%;
  bottom: 22px;
  z-index: 10000;
  transform: translate(-50%, 12px);
  max-width: min(440px, calc(100vw - 32px));
  padding: 11px 15px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 999px;
  color: #ffffff;
  background: #0d6f61;
  box-shadow: 0 14px 32px rgba(8, 42, 37, 0.26);
  font-size: 13px;
  font-weight: 900;
  line-height: 1.2;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
}

.app-toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.login-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
}

.login-panel {
  width: min(1120px, 100%);
  min-height: 680px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 390px;
  gap: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow);
}

.login-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 52px;
  border-right: 1px solid var(--line);
}

.login-kicker,
.panel-label {
  width: fit-content;
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  padding: 0 10px;
  border: 1px solid rgba(13, 111, 97, 0.24);
  border-radius: 999px;
  color: var(--teal);
  background: var(--teal-soft);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.brand-row {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 11px;
  margin: 16px 0 30px;
}

.topbar-brand {
  margin: 0;
}

.brand-home-btn {
  width: fit-content;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.brand-home-btn:hover .brand-mark,
.brand-home-btn:focus-visible .brand-mark {
  border-color: rgba(13, 111, 97, 0.45);
  box-shadow: 0 10px 24px rgba(13, 111, 97, 0.2);
}

.brand-home-btn:focus-visible {
  outline: 3px solid rgba(13, 111, 97, 0.22);
  outline-offset: 5px;
  border-radius: 12px;
}

.brand-copy {
  min-width: 0;
  display: grid;
}

.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  overflow: hidden;
  flex: 0 0 auto;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 8px 18px rgba(17, 24, 21, 0.12);
}

.brand-mark img {
  width: 100%;
  height: 100%;
  display: block;
}

.brand-name {
  font-size: 16px;
  line-height: 1.15;
  font-weight: 850;
}

.company-pill,
.user-pill,
.status-pill {
  min-height: 30px;
  display: inline-flex;
  align-items: center;
  width: fit-content;
  max-width: 100%;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--panel-strong);
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
}

.company-pill,
.user-pill {
  margin-top: 4px;
  padding: 0 10px;
}

.status-pill {
  padding: 0 11px;
}

.status-pill.is-live {
  border-color: rgba(13, 111, 97, 0.26);
  color: var(--teal);
  background: var(--teal-soft);
}

.build-version-pill {
  border-color: rgba(45, 101, 155, 0.3);
  color: #24527e;
  background: var(--blue-soft);
}

.build-version-btn {
  font: inherit;
  cursor: pointer;
}

.build-version-btn:hover,
.build-version-btn:focus-visible {
  border-color: rgba(45, 101, 155, 0.5);
  color: #153c61;
  box-shadow: 0 8px 18px rgba(45, 101, 155, 0.14);
}

.build-version-btn:focus-visible {
  outline: 3px solid rgba(45, 101, 155, 0.18);
  outline-offset: 3px;
}

.focus-mode-pill {
  border-color: rgba(13, 111, 97, 0.34);
  color: #0a4d44;
  background: linear-gradient(135deg, rgba(236, 247, 243, 0.96), rgba(255, 255, 255, 0.92));
}

body.quiet-focus-mode .focus-mode-pill {
  border-color: rgba(13, 111, 97, 0.62);
  color: #fff;
  background: linear-gradient(135deg, #137f70, #0d6f61);
  box-shadow: 0 10px 22px rgba(13, 111, 97, 0.14);
}

.serenity-mode-pill {
  border-color: rgba(13, 111, 97, 0.26);
  color: var(--teal-dark);
  background: rgba(236, 247, 243, 0.92);
}

.serenity-mode-pill:hover,
.serenity-mode-pill:focus-visible {
  border-color: rgba(13, 111, 97, 0.52);
  color: var(--teal-dark);
  background: linear-gradient(135deg, #fbfefc, var(--teal-soft));
  outline: none;
}

.serenity-mode-pill.active {
  border-color: rgba(13, 111, 97, 0.72);
  color: #fff;
  background: linear-gradient(135deg, #137f70, #0d6f61);
  box-shadow: 0 10px 22px rgba(13, 111, 97, 0.16);
}

.preview-pill {
  border-color: rgba(184, 110, 23, 0.34);
  color: #77450e;
  background: var(--amber-soft);
}

.login-copy h1 {
  max-width: 720px;
  margin: 0;
  color: var(--ink);
  font-size: 64px;
  line-height: 0.98;
}

.login-copy p {
  max-width: 700px;
  margin: 18px 0 0;
  color: var(--muted);
  font-size: 17px;
  line-height: 1.55;
}

.login-signal-strip,
.status-strip,
.topbar-actions,
.mode-nav,
.account-actions,
.toolbar-actions,
.row-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.login-signal-strip {
  margin-top: 22px;
}

.login-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 36px;
}

.login-stat {
  min-height: 96px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel-strong);
}

.login-stat strong {
  display: block;
  color: var(--ink);
  font-size: 30px;
  line-height: 1;
}

.login-stat span {
  display: block;
  margin-top: 10px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.35;
}

.login-form-wrap {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 34px;
  background: linear-gradient(180deg, #ffffff, #f8faf6);
}

.logo-showcase {
  width: min(235px, 72%);
  margin: 0 auto 22px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #ffffff;
}

.logo-showcase img {
  display: block;
  width: 100%;
  height: auto;
}

.login-form-wrap h2 {
  margin: 12px 0 18px;
  font-size: 28px;
  line-height: 1.1;
}

.field {
  display: grid;
  gap: 7px;
  margin-bottom: 14px;
}

.field label {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.field input,
.field select,
.field textarea,
.filter-input,
.filter-select {
  width: 100%;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: #ffffff;
  color: var(--ink);
  outline: none;
}

.field input,
.field select,
.filter-input,
.filter-select {
  min-height: 42px;
  padding: 0 12px;
}

.field textarea {
  min-height: 96px;
  resize: vertical;
  padding: 10px 12px;
}

.field input:focus,
.field select:focus,
.field textarea:focus,
.filter-input:focus,
.filter-select:focus,
[contenteditable="true"]:focus {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(13, 111, 97, 0.14);
}

.primary-btn,
.secondary-btn,
.ghost-btn,
.danger-btn {
  text-decoration: none;
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 14px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 850;
  white-space: nowrap;
}

.primary-btn {
  color: #ffffff;
  background: var(--ink);
  border: 1px solid var(--ink);
}

.secondary-btn {
  color: #ffffff;
  background: var(--teal);
  border: 1px solid var(--teal);
}

.ghost-btn {
  color: var(--ink-soft);
  background: var(--panel);
  border: 1px solid var(--line);
}

.admin-membership-btn {
  border-color: rgba(13, 111, 97, 0.32);
  color: var(--teal-dark);
  background: var(--teal-soft);
}

.admin-membership-btn.active {
  color: #ffffff;
  background: var(--teal);
  border-color: var(--teal);
}

.admin-tools-launcher {
  position: relative;
  flex: 0 0 auto;
}

.admin-tools-btn {
  min-width: 132px;
  border-color: rgba(13, 111, 97, 0.32);
  color: var(--teal-dark);
  background: var(--teal-soft);
}

.admin-tools-btn.active {
  color: #ffffff;
  background: var(--teal);
  border-color: var(--teal);
}

.admin-tools-btn small {
  min-width: 22px;
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  color: var(--teal-dark);
  background: rgba(255, 255, 255, 0.72);
  font-size: 11px;
  font-weight: 950;
}

.admin-tools-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 45;
  width: min(430px, calc(100vw - 32px));
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 22px 54px rgba(17, 24, 21, 0.16);
}

.admin-tools-note {
  margin-bottom: 10px;
  padding: 9px 10px;
  border: 1px solid rgba(13, 111, 97, 0.16);
  border-left: 4px solid var(--teal);
  border-radius: 8px;
  color: var(--ink-soft);
  background: var(--teal-soft);
  font-size: 12px;
  line-height: 1.35;
}

.admin-tools-grid {
  display: grid;
  gap: 8px;
}

.admin-tools-card {
  min-height: 78px;
  display: grid;
  gap: 5px;
  padding: 12px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: 8px;
  color: var(--ink);
  text-decoration: none;
  background: var(--panel-strong);
}

.admin-tools-card:hover,
.admin-tools-card.active {
  box-shadow: inset 0 0 0 1px rgba(17, 24, 21, 0.08), 0 8px 18px rgba(17, 24, 21, 0.08);
}

.admin-tools-card span {
  color: var(--ink);
  font-size: 14px;
  font-weight: 950;
  line-height: 1.15;
}

.admin-tools-card small {
  color: var(--ink-soft);
  font-size: 12px;
  line-height: 1.35;
}

.admin-tools-card.tone-green {
  border-color: rgba(36, 119, 71, 0.26);
  border-left-color: var(--green);
  background: var(--green-soft);
}

.admin-tools-card.tone-amber {
  border-color: rgba(184, 110, 23, 0.26);
  border-left-color: var(--amber);
  background: var(--amber-soft);
}

.admin-tools-card.tone-blue {
  border-color: rgba(49, 95, 147, 0.26);
  border-left-color: var(--blue);
  background: var(--blue-soft);
}

.danger-btn {
  color: var(--red);
  background: var(--red-soft);
  border: 1px solid rgba(179, 59, 48, 0.24);
}

.demo-users {
  margin-top: 18px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--muted);
  background: var(--panel-strong);
  font-size: 13px;
  line-height: 1.65;
}

.demo-users code {
  color: var(--ink);
  font-family: var(--mono);
  font-size: 12px;
}

.message {
  min-height: 22px;
  margin: 10px 0 0;
  color: var(--red);
  font-size: 13px;
}

.shell {
  min-height: 100vh;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  min-height: 66px;
  display: grid;
  grid-template-columns: minmax(240px, 1fr) auto;
  align-items: center;
  gap: 8px 14px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
}

.status-strip {
  justify-content: flex-end;
}

.topbar-actions {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  width: 100%;
  justify-content: stretch;
}

.nav-shell {
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}

.mode-nav {
  min-width: 0;
  flex: 1 1 auto;
  flex-wrap: wrap;
  overflow: visible;
  justify-content: flex-start;
  gap: 7px;
  padding-bottom: 2px;
  scrollbar-width: none;
}

.mode-nav::-webkit-scrollbar {
  display: none;
}

.rooms-launcher {
  position: relative;
  flex: 0 0 auto;
}

.rooms-btn {
  border-color: rgba(184, 110, 23, 0.28);
  color: #77450e;
  background: var(--amber-soft);
}

.rooms-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  z-index: 40;
  width: min(620px, calc(100vw - 32px));
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 22px 54px rgba(17, 24, 21, 0.16);
}

.rooms-menu-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
  padding: 0 2px;
}

.rooms-menu-head span {
  color: var(--ink);
  font-size: 12px;
  font-weight: 950;
  text-transform: uppercase;
}

.rooms-memory-strip {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  margin-bottom: 10px;
  padding: 10px;
  border: 1px solid rgba(49, 95, 147, 0.2);
  border-left: 4px solid var(--blue);
  border-radius: 8px;
  background: var(--blue-soft);
}

.rooms-memory-strip span {
  color: var(--blue);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
}

.rooms-memory-strip strong {
  display: block;
  margin-top: 3px;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.15;
}

.rooms-memory-strip p {
  margin: 4px 0 0;
  color: var(--ink-soft);
  font-size: 11px;
  line-height: 1.35;
}

.rooms-memory-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  max-width: 280px;
}

.rooms-memory-actions button {
  min-height: 30px;
  padding: 6px 9px;
  border: 1px solid rgba(49, 95, 147, 0.2);
  border-radius: 8px;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.78);
  font-size: 10px;
  font-weight: 950;
  line-height: 1.1;
}

.rooms-memory-actions .rooms-memory-primary {
  color: #ffffff;
  background: var(--blue);
}

.rooms-preference-controls {
  margin-bottom: 10px;
  padding: 10px;
  border: 1px solid rgba(13, 111, 97, 0.2);
  border-left: 4px solid var(--teal);
  border-radius: 8px;
  background: linear-gradient(135deg, rgba(232, 246, 240, 0.82), rgba(255, 255, 255, 0.95));
}

.rooms-preference-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.rooms-preference-head span,
.rooms-preference-pins > span {
  color: var(--teal-dark);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
}

.rooms-preference-head strong {
  display: block;
  margin-top: 3px;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.15;
}

.rooms-preference-profile {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-bottom: 8px;
}

.rooms-preference-profile div {
  min-height: 50px;
  padding: 8px;
  border: 1px solid rgba(13, 111, 97, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.72);
}

.rooms-preference-profile span {
  display: block;
  color: var(--muted);
  font-size: 9px;
  font-weight: 950;
  text-transform: uppercase;
}

.rooms-preference-profile strong {
  display: block;
  margin-top: 5px;
  color: var(--ink);
  font-size: 13px;
  line-height: 1.15;
}

.rooms-preset-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin-bottom: 8px;
}

.rooms-preset-card {
  display: grid;
  gap: 4px;
  min-height: 112px;
  padding: 10px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: 8px;
  color: var(--ink);
  text-align: left;
  background: rgba(255, 255, 255, 0.78);
}

.rooms-preset-card:hover,
.rooms-preset-card.active {
  transform: translateY(-1px);
  box-shadow: 0 10px 22px rgba(17, 24, 21, 0.08);
}

.rooms-preset-card.tone-teal {
  border-color: rgba(13, 111, 97, 0.24);
  border-left-color: var(--teal);
  background: var(--teal-soft);
}

.rooms-preset-card.tone-green {
  border-color: rgba(36, 119, 71, 0.24);
  border-left-color: var(--green);
  background: var(--green-soft);
}

.rooms-preset-card.tone-amber {
  border-color: rgba(184, 110, 23, 0.28);
  border-left-color: var(--amber);
  background: var(--amber-soft);
}

.rooms-preset-card.tone-blue {
  border-color: rgba(49, 95, 147, 0.24);
  border-left-color: var(--blue);
  background: var(--blue-soft);
}

