.morning-flow-panel {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow-soft);
}

.morning-flow-head {
  margin: 0;
}

.morning-flow-head h3 {
  margin: 2px 0 0;
  font-size: 18px;
  line-height: 1.2;
}

.morning-flow-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.morning-flow-card {
  display: grid;
  align-content: start;
  gap: 8px;
  min-width: 0;
  min-height: 152px;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--ink);
}

.morning-flow-time {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.morning-flow-time span {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 3px 8px;
  border: 1px solid rgba(18, 130, 113, 0.2);
  border-radius: 999px;
  background: rgba(223, 245, 239, 0.82);
  color: var(--teal-dark);
  font-size: 11px;
  font-weight: 950;
}

.morning-flow-time b {
  color: var(--teal-dark);
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.morning-flow-card h4 {
  margin: 0;
  color: var(--ink);
  font-size: 16px;
  line-height: 1.22;
}

.morning-flow-card p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.morning-flow-card .mini-btn {
  align-self: end;
  justify-self: start;
}

.morning-flow-card.tone-red {
  border-color: rgba(196, 56, 51, 0.34);
  border-left-color: #c43b33;
  background: linear-gradient(135deg, #fffdfb, var(--red-soft));
}

.morning-flow-card.tone-amber {
  border-color: rgba(198, 116, 23, 0.34);
  border-left-color: #c77617;
  background: linear-gradient(135deg, #fffdf8, var(--amber-soft));
}

.morning-flow-card.tone-blue {
  border-color: rgba(49, 101, 158, 0.32);
  border-left-color: #31659e;
  background: linear-gradient(135deg, #fbfdff, var(--blue-soft));
}

.morning-flow-card.tone-green {
  border-color: rgba(40, 131, 74, 0.32);
  border-left-color: #27834a;
  background: linear-gradient(135deg, #fbfefc, var(--green-soft));
}

.morning-brief-strip {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.95);
  box-shadow: var(--shadow-soft);
}

.morning-brief-head {
  margin: 0;
}

.morning-brief-head h3 {
  margin: 2px 0 0;
  font-size: 18px;
  line-height: 1.2;
}

.morning-brief-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.morning-brief-card {
  display: grid;
  align-content: start;
  gap: 7px;
  min-width: 0;
  min-height: 116px;
  padding: 13px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--ink);
}

.morning-brief-card span {
  color: var(--teal-dark);
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.morning-brief-card strong {
  color: var(--ink);
  font-size: 15px;
  line-height: 1.24;
}

.morning-brief-card p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.morning-brief-card.tone-red {
  border-color: rgba(196, 56, 51, 0.34);
  border-left-color: #c43b33;
  background: linear-gradient(135deg, #fffdfb, var(--red-soft));
}

.morning-brief-card.tone-amber {
  border-color: rgba(198, 116, 23, 0.34);
  border-left-color: #c77617;
  background: linear-gradient(135deg, #fffdf8, var(--amber-soft));
}

.morning-brief-card.tone-blue {
  border-color: rgba(49, 101, 158, 0.32);
