}

.morning-brief-receipt-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.morning-brief-receipt-title strong {
  color: var(--ink);
  font-size: 14px;
  line-height: 1.25;
  text-align: right;
}

.morning-brief-receipt-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.morning-brief-receipt-card {
  display: grid;
