  min-height: 86px;
  padding: 11px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--ink);
}

.morning-brief-receipt-card span {
  color: var(--teal-dark);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
}

.morning-brief-receipt-card strong {
  color: var(--ink);
  font-size: 15px;
  line-height: 1.2;
}

.morning-brief-receipt-card small {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.morning-brief-receipt-card.tone-red {
  border-color: rgba(196, 56, 51, 0.34);
  border-left-color: #c43b33;
  background: linear-gradient(135deg, #fffdfb, var(--red-soft));
}

.morning-brief-receipt-card.tone-amber {
  border-color: rgba(198, 116, 23, 0.34);
  border-left-color: #c77617;
  background: linear-gradient(135deg, #fffdf8, var(--amber-soft));
}

.morning-brief-receipt-card.tone-blue {
  border-color: rgba(49, 101, 158, 0.32);
  border-left-color: #31659e;
  background: linear-gradient(135deg, #fbfdff, var(--blue-soft));
}

.morning-brief-receipt-card.tone-green {
  border-color: rgba(40, 131, 74, 0.32);
