.autopilot-console {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 20px;
  align-items: center;
  min-height: 270px;
  padding: 24px;
  overflow: hidden;
  position: relative;
  border: 1px solid rgba(13, 111, 97, 0.26);
  border-bottom: 3px solid var(--teal);
  border-radius: var(--radius);
  color: #ffffff;
  background:
    radial-gradient(circle at 78% 24%, rgba(255, 255, 255, 0.16), transparent 25%),
    linear-gradient(135deg, #0f7c6d, #123c37 50%, #101b1a);
  box-shadow: var(--shadow-strong);
}

.autopilot-console::after {
  content: "";
  position: absolute;
  right: -120px;
  bottom: -170px;
  width: 420px;
  height: 420px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;
}

.autopilot-console > * {
