.command-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  gap: 12px;
  align-items: start;
}

.command-main {
  min-width: 0;
  display: grid;
  gap: 12px;
}

.command-main-head {
  min-height: 0;
  margin: 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow);
}

.command-side {
  position: sticky;
  top: 82px;
  display: grid;
  gap: 12px;
}

.command-module-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.command-module-card {
  min-height: 156px;
  display: grid;
  gap: 8px;
  align-content: start;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: var(--radius);
  color: var(--ink);
  background: rgba(255, 255, 255, 0.96);
  text-align: left;
  box-shadow: var(--shadow);
}

.command-module-card:hover {
  transform: translateY(-1px);
  border-color: rgba(13, 111, 97, 0.32);
  background: #f7fbf8;
}

.command-module-card:disabled {
  cursor: not-allowed;
  opacity: 0.52;
  transform: none;
}

.command-module-card.tone-blue {
  border-left-color: var(--blue);
}

.command-module-card.tone-green {
  border-left-color: var(--green);
}

.command-module-card.tone-amber {
  border-left-color: var(--amber);
}

.command-module-card.tone-red {
  border-left-color: var(--red);
}

.command-module-card span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 950;
  text-transform: uppercase;
}

.command-module-card strong {
  color: var(--ink);
  font-size: 30px;
  line-height: 1;
}

.command-module-card small,
.command-module-card em {
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
  line-height: 1.35;
}

.command-module-card em {
  width: fit-content;
  margin-top: auto;
  padding: 5px 8px;
  border-radius: 999px;
  color: var(--teal-dark);
  background: var(--teal-soft);
  font-weight: 900;
}

.command-module-card.tone-blue em {
  color: var(--blue);
  background: var(--blue-soft);
}

.command-module-card.tone-amber em {
  color: var(--amber);
  background: var(--amber-soft);
}

.command-module-card.tone-red em {
  color: var(--red);
  background: var(--red-soft);
}

.command-module-card.tone-teal,
.command-module-card.tone-blue {
  color: #ffffff;
}

.command-module-card.tone-teal span,
.command-module-card.tone-teal strong,
.command-module-card.tone-blue span,
.command-module-card.tone-blue strong {
  color: #ffffff;
}

.command-module-card.tone-teal small,
.command-module-card.tone-blue small {
  color: rgba(255, 255, 255, 0.82);
}

.command-module-card.tone-teal em,
.command-module-card.tone-blue em {
  color: var(--teal-dark);
  background: rgba(255, 255, 255, 0.92);
}

.command-module-card.tone-amber span,
.command-module-card.tone-amber strong {
  color: #111815;
}

.command-module-card.tone-amber small {
  color: rgba(17, 24, 21, 0.82);
}

.command-module-card.tone-amber em {
  color: #8a4300;
  background: rgba(255, 255, 255, 0.92);
}

