  color: var(--muted);
}

.annual-price,
.price-note {
  margin: 0;
  line-height: 1.42;
}

.annual-price {
  color: #76480e;
  font-size: 13px;
  font-weight: 950;
}

.pricing-feature-list {
  display: grid;
  gap: 7px;
  margin: 0;
  padding-left: 18px;
  color: var(--muted);
  line-height: 1.35;
}

.pricing-feature-list li::marker {
  color: var(--teal);
}

.plan-link {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: end;
  margin-top: 4px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  background: var(--panel-strong);
  font-size: 12px;
  font-weight: 900;
  text-decoration: none;
}

.plan-link:hover {
  border-color: var(--line-strong);
  background: var(--teal-soft);
}

.plan-link.muted {
  color: var(--muted);
}

.pricing-note-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 12px;
}

.pricing-note {
  padding: 14px;
}

.pricing-note strong {
  display: block;
  margin-top: 4px;
  color: var(--ink);
  font-size: 17px;
}

.pricing-note p {
  margin: 8px 0 0;
  color: var(--muted);
  line-height: 1.45;
}

.pricing-compare {
  margin-top: 12px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
}

.compare-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
}

.compare-head strong {
  display: block;
  color: var(--ink);
  font-size: 18px;
  line-height: 1.2;
}

.compare-grid {
  display: grid;
  gap: 6px;
}

.compare-row {
  display: grid;
  grid-template-columns: minmax(190px, 1.4fr) repeat(4, minmax(110px, 1fr));
  gap: 6px;
}

.compare-row span {
  min-height: 38px;
  display: flex;
  align-items: center;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 7px;
  color: var(--muted);
  background: var(--panel-strong);
  font-size: 12px;
  font-weight: 850;
}

.compare-row span:first-child {
  color: var(--ink-soft);
  background: #ffffff;
}

.compare-row-head span {
  color: var(--teal);
  background: var(--teal-soft);
  text-transform: uppercase;
}

.billing-faq-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 12px;
}

.billing-faq-grid article {
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
}

.billing-faq-grid strong {
  display: block;
  margin-top: 4px;
  color: var(--ink);
  font-size: 17px;
  line-height: 1.25;
}

.billing-faq-grid p {
  margin: 8px 0 0;
  color: var(--muted);
  line-height: 1.45;
}

.readonly-note {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--muted);
  background: var(--panel-strong);
  line-height: 1.5;
}

.floating-tools {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 40;
  display: grid;
  gap: 9px;
}

.float-btn {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 16px 34px rgba(17, 24, 21, 0.22);
}

.float-btn:hover {
  background: var(--teal-dark);
}

.arrow-float {
  background: var(--ink);
}

.search-icon {
  position: relative;
  width: 18px;
  height: 18px;
  border: 3px solid #ffffff;
  border-radius: 50%;
}

.search-icon::after {
  content: "";
  position: absolute;
  width: 10px;
  height: 3px;
  right: -8px;
  bottom: -5px;
  border-radius: 999px;
  background: #ffffff;
  transform: rotate(45deg);
}

.arrow-icon {
  position: relative;
  width: 18px;
  height: 18px;
}

.arrow-icon::before,
.arrow-icon::after {
  content: "";
  position: absolute;
  left: 50%;
  background: #ffffff;
}

.arrow-icon::before {
  top: 2px;
  width: 3px;
  height: 15px;
  border-radius: 999px;
  transform: translateX(-50%);
}

.arrow-icon::after {
  top: 2px;
  width: 12px;
  height: 12px;
  border-top: 3px solid #ffffff;
  border-left: 3px solid #ffffff;
  background: transparent;
  transform: translateX(-50%) rotate(45deg);
}

.quick-search-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: start center;
  padding: 78px 16px 20px;
  background: rgba(17, 24, 21, 0.46);
}

.quick-search-panel {
  width: min(760px, 100%);
  max-height: min(760px, calc(100vh - 100px));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 28px 80px rgba(17, 24, 21, 0.28);
}

.quick-search-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 14px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}

.quick-search-head h2 {
  margin: 8px 0 0;
  color: var(--ink);
  font-size: 21px;
  line-height: 1.18;
}

.quick-search-input {
  width: calc(100% - 28px);
  min-height: 50px;
  margin: 14px;
  padding: 0 14px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  color: var(--ink);
  background: #ffffff;
  font-size: 16px;
}

.quick-search-results {
  display: grid;
  gap: 8px;
  max-height: 520px;
  overflow: auto;
  padding: 0 14px 14px;
}

.quick-search-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 2px 0;
  color: var(--teal-dark);
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.quick-search-section-title em {
  color: var(--muted);
  font-style: normal;
  text-transform: none;
}

.quick-result {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(130px, 0.35fr) minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  background: var(--panel-strong);
  text-align: left;
}

.quick-result:hover {
  border-color: rgba(13, 111, 97, 0.32);
  background: var(--teal-soft);
}

.quick-room-result {
  border-left: 4px solid var(--teal);
  background: var(--teal-soft);
}

.quick-room-result.tone-green,
.quick-room-result.tone-teal {
  border-left-color: var(--teal);
  background: var(--teal-soft);
}

.quick-room-result.tone-blue {
  border-left-color: var(--blue);
  background: var(--blue-soft);
}

.quick-room-result.tone-amber {
  border-left-color: var(--amber);
  background: var(--amber-soft);
}

.quick-room-result.tone-red {
  border-left-color: var(--red);
  background: var(--red-soft);
}

.quick-result strong,
.quick-result em {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quick-result strong {
  color: var(--ink);
  font-size: 13px;
}

.quick-result em {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

